fn predicate(e : Expr, columns : List(Column), allow : Bool) : Expr =
  let b = check(e, columns, allow, false)
  demand(fits(b.kind, "bool"), "TYPE_ERROR")
  b

fn find_table(database : List(Table), name : String) : Table =
  let ts = filter(\(t) -> t.name == name, database)
  demand(length(ts) > 0, "UNKNOWN_TABLE")
  at(ts, 0)

fn bind(q : Query, database : List(Table)) : Plan =
  let aliases = map(snd, q.select)
  demand(unique(aliases), "DUPLICATE_ALIAS")
  demand(unique(map(snd, q.sources)), "DUPLICATE_ALIAS")
  let tables = map(\(s) -> find_table(database, fst(s)), q.sources)
  var columns := []
  var joins := []
  for i in srange(0, length(tables)) do
    let t = at(tables, i)
    let offset = length(columns)
    let qualifier = snd(at(q.sources, i))
    -- The right side of a LEFT JOIN may be padded with NULL, so every one of
    -- its columns is nullable downstream regardless of its declaration.
    let padded = i > 0 && at(q.outer, i - 1)
    let cs = map(
        \(k) -> let c = at(t.columns, k) in Column { ..c, index = offset + k, source = i, qualifier = qualifier, nullable = c.nullable || padded },
        range(0, length(t.columns)),
      )
    columns := append(columns, cs)
    if i > 0 then
      joins := append(joins, [predicate(at(q.joins, i - 1), columns, false)])
  let cs = columns
  let sels = map(\(s) -> (check(fst(s), cs, true, false), snd(s)), q.select)
  let groups = map(\(e) -> check(e, cs, false, false), q.groups)
  let keys = map(\(e) -> e.index, groups)
  demand(unique(map(show_int, keys)), "INVALID_AGGREGATION")
  let pred = predicate(q.predicate, cs, false)
  let hav = predicate(q.having, cs, true)
  let roots = append(map(fst, sels), [hav])
  let aggregate =
    length(groups) > 0 || any(\(e) -> tree_any(\(n) -> agg(n.op), e), roots)
  demand(not(q.has_having) || aggregate, "INVALID_AGGREGATION")
  if aggregate then
    for e in sof(roots) do
      grouped(e, keys)
  let order = map(\(o) -> let (n, desc, nf) = o in (alias_index(aliases, n, 0), desc, nf), q.order)
  let bq =
    Query {
      ..q,
      select = sels,
      joins = joins,
      groups = groups,
      predicate = pred,
      having = hav
    }
  Plan {
    query = bq,
    tables = tables,
    filters = map(\(_) -> [], tables),
    aggregate = aggregate,
    order = order
  }

fn combine(es : List(Expr)) : Expr =
  match filter(\(e) -> not(is_true_literal(e)), es) of
    Nil => literal(JBool(true))
    Cons(e, Nil) => e
    Cons(e, rest) => Expr { ..node("AND", [e, combine(rest)]), kind = "bool" }

fn single_source(e : Expr) : Int =
  let ss = sources(e)
  if length(ss) > 0 && all(\(s) -> s == at(ss, 0), ss) then
    at(ss, 0)
  else
    -1

fn optimize(plan : Plan) : Plan =
  let q = plan.query
  let width = sum(map(\(t) -> length(t.columns), plan.tables))
  let terms = conjuncts(fold_constants(q.predicate))
  var outer := q.outer
  var fs := map(\(_) -> [], plan.tables)
  var rem := []
  for e in sof(terms) do
    let s = single_source(e)
    let padded = s > 0 && at(outer, s - 1)
    if s >= 0 && length(plan.tables) > 1 && (not(padded) || null_rejecting(e, width)) then
      if padded then
        outer := map(\(i) -> at(outer, i) && i /= s - 1, range(0, length(outer)))
      fs := map(\(i) -> if i == s then append(at(fs, i), [e]) else at(fs, i), range(0, length(fs)))
    else
      rem := append(rem, [e])
  let bq = Query {
    ..q,
    predicate = combine(rem),
    outer = outer,
    select = map(\(s) -> (fold_constants(fst(s)), snd(s)), q.select),
    joins = map(fold_constants, q.joins),
    having = fold_constants(q.having)
  }
  Plan { ..plan, query = bq, filters = fs }

fn execute(plan : Plan) : Json =
  let q = plan.query
  var scans := []
  var offset := 0
  for i in srange(0, length(plan.tables)) do
    let t = at(plan.tables, i)
    let padding = replicate(offset, JNull)
    let predicates = at(plan.filters, i)
    let rs = filter(
        \(r) -> all(\(p) -> truth(evaluate(p, append(padding, r), [])), predicates),
        t.rows,
      )
    scans := append(scans, [rs])
    offset += length(t.columns)
  var rows := at(scans, 0)
  for i in srange(0, length(q.joins)) do
    let width = length(at(plan.tables, i + 1).columns)
    rows := join_rows(rows, at(scans, i + 1), at(q.joins, i), at(q.outer, i), width)
  let filtered = filter(\(r) -> truth(evaluate(q.predicate, r, [])), rows)
  let projected =
    if plan.aggregate then
      flatten(
          map(
              \(g) -> project(q, if length(g.rows) > 0 then at(g.rows, 0) else [], g.rows),
              groups_for(filtered, q.groups),
            ),
        )
    else
      flatten(map(\(r) -> project(q, r, []), filtered))
  let distinct =
    if q.distinct then
      distinct_rows(projected, [])
    else
      projected
  let sorted =
    if length(plan.order) > 0 then
      sort_rows(distinct, plan.order)
    else
      distinct
  let skipped = drop(q.offset, sorted)
  let final =
    if q.limit >= 0 then
      take(q.limit, skipped)
    else
      skipped
  JObj([
      ("columns", JArr(map(\(s) -> JStr(snd(s)), q.select))),
      ("rows", JArr(map(JArr, final))),
    ])

fn demand(b : Bool, code : String) : Unit =
  if not(b) then
    reject(code)

fn reserved(s : String) : Bool =
  elem(
      to_upper(s),
      split(
          32,
          "SELECT DISTINCT AS FROM INNER JOIN LEFT OUTER ON WHERE GROUP BY HAVING ORDER ASC DESC NULLS FIRST LAST LIMIT OFFSET AND OR NOT IS NULL TRUE FALSE COALESCE COUNT SUM MIN MAX",
        ),
    )

type Table = Table {
  name: String,
  columns: List(Column),
  rows: List(List(Json))
}

fn validate_table(j : Json) : Table =
  fields(j, ["name", "columns", "rows"])
  let n = text(getfield(j, "name"))
  demand(name_ok(n), "INVALID_INPUT")
  let cs = map(validate_column, arr(getfield(j, "columns")))
  demand(length(cs) > 0, "INVALID_INPUT")
  demand(unique(map(\(c) -> c.name, cs)), "INVALID_INPUT")
  let rows = map(arr, arr(getfield(j, "rows")))
  for row in sof(rows) do
    demand(length(row) == length(cs), "INVALID_INPUT")
    for i in srange(0, length(cs)) do
      let c = at(cs, i)
      let v = at(row, i)
      demand(value_type(v) == c.kind || is_null(v) && c.nullable, "INVALID_INPUT")
  Table { name = n, columns = cs, rows = rows }

fn validate_column(j : Json) : Column =
  fields(j, ["name", "type", "nullable"])
  let n = text(getfield(j, "name"))
  let t = text(getfield(j, "type"))
  demand(name_ok(n) && elem(t, ["int", "text", "bool"]), "INVALID_INPUT")
  let nullable =
    match getfield(j, "nullable") of
      JBool(b) => b
      _ =>
        reject("INVALID_INPUT")
        false
  Column {
    name = n,
    kind = t,
    nullable = nullable,
    qualifier = "",
    source = 0,
    index = 0
  }

fn pop() : Token ! {State(List(Token)), Domain} =
  let ts = get()
  let t = at(ts, 0)
  demand(t.word /= "$END", "PARSE_ERROR")
  put(tail(ts))
  t

fn natural() : Int =
  let t = pop()
  demand(t.word == "NUMBER", "PARSE_ERROR")
  integer(t.value)

fn reference() : Expr =
  let n = name()
  if accept(".") then
    column_ref(n, name())
  else
    column_ref("", n)

fn source() : (String, String) =
  let n = name()
  (n, if accept("AS") then name() else n)

fn arguments() : List(Expr) =
  let e = expression(1)
  Cons(e, if accept(",") then arguments() else [])

fn binary(left : Expr, minimum : Int, compared : Bool) : Expr =
  let op = peek()
  let p = precedence(op)
  if p < minimum then
    left
  else
    demand(not(p == 4 && compared), "PARSE_ERROR")
    let ignored = pop()
    if op == "IS" then
      let negated = accept("NOT")
      expect("NULL")
      binary(node(if negated then "ISNOTNULL" else "ISNULL", [left]), minimum, true)
    else
      let right = expression(p + 1)
      binary(node(op, [left, right]), minimum, compared || p == 4)

fn selections() : List((Expr, String)) =
  let e = expression(1)
  expect("AS")
  let a = name()
  Cons((e, a), if accept(",") then selections() else [])

fn group_keys() : List(Expr) =
  let e = reference()
  Cons(e, if accept(",") then group_keys() else [])

fn order_keys() : List((String, Bool, Bool)) =
  let n = name()
  let desc = accept("DESC")
  if not(desc) then
    let ignored = accept("ASC")
    ()
  let nulls_first =
    if accept("NULLS") then
      if accept("FIRST") then
        true
      else
        expect("LAST")
        false
    else
      desc
  Cons((n, desc, nulls_first), if accept(",") then order_keys() else [])

fn join_sources(
  ss : List((String, String)),
  js : List(Expr),
  os : List(Bool)
) : (List((String, String)), List(Expr), List(Bool)) =
  let left = accept("LEFT")
  if left then
    let ignored = accept("OUTER")
    ()
  if left || elem(peek(), ["INNER", "JOIN"]) then
    if not(left) then
      let ignored = accept("INNER")
      ()
    expect("JOIN")
    let s = source()
    expect("ON")
    let e = expression(1)
    join_sources(append(ss, [s]), append(js, [e]), append(os, [left]))
  else
    (ss, js, os)

fn validate_query(q : Json) : Unit =
  fields(q, ["sql", "optimize"])
  let ignored = text(getfield(q, "sql"))
  match getfield(q, "optimize") of
    JBool(_) => ()
    _ => reject("INVALID_INPUT")

fn work(request : Json) : Json =
  demand(
      value_type(getfield(request, "protocol_version")) == "int"
        && integer(getfield(request, "protocol_version")) == 1,
      "INVALID_INPUT",
    )
  demand(text(getfield(request, "task")) == "query-null", "INVALID_INPUT")
  let input = getfield(request, "input")
  fields(input, ["database", "queries"])
  let database = map(validate_table, arr(getfield(input, "database")))
  demand(unique(map(\(t) -> t.name, database)), "INVALID_INPUT")
  let queries = arr(getfield(input, "queries"))
  for q in sof(queries) do
    validate_query(q)
  let results = map(
      \(q) -> let plan = bind(parse_sql(text(getfield(q, "sql"))), database) in execute(if truth(getfield(q, "optimize")) then optimize(plan) else plan),
      queries,
    )
  JObj([("ok", JBool(true)), ("result", JObj([("results", JArr(results))]))])

fn main() =
  let line = read_line()
  let response =
    handle decode_work(line) with
      never reject(code) => error_response(code)
      return result => result
  println(encode(response))
